function fixJson(src){
  var s=String(src||''), out='', i=0, inStr=false;
  while(i<s.length){
    var c=s[i];
    if(c==='\\'){ out+=s[i]+(s[i+1]||''); i+=2; continue; }
    if(c==='"'){ inStr=!inStr; out+=c; i++; continue; }
    if(c==="'" && !inStr){
      var j=i+1, buf='';
      while(j<s.length){
        var d=s[j];
        if(d==='\\'){ buf+=d+(s[j+1]||''); j+=2; continue; }
        if(d==="'"){ break; }
        buf+=d; j++;
      }
      out+='"'+buf.replace(/"/g,'\\"')+'"'; i=j+1; continue;
    }
    if(inStr){ out+=c; i++; continue; }
    if(c==='/' && s[i+1]==='/'){ while(i<s.length && s[i]!=='\n') i++; continue; }
    if(c==='/' && s[i+1]==='*'){ i+=2; while(i<s.length && !(s[i]==='*'&&s[i+1]==='/')) i++; i+=2; continue; }
    out+=c; i++;
  }
  out=out.replace(/,(\s*[}\]])/g,'$1');
  out=out.replace(/([{,]\s*)([A-Za-z_$][A-Za-z0-9_$]*)\s*:/g,'$1"$2":');
  out=out.replace(/\b(NaN|Infinity|-Infinity|undefined)\b/g,'null');
  return out;
}
function tryParseJson(s){ try { var v=JSON.parse(s); return {ok:true, value:JSON.stringify(v,null,2)}; } catch(e){ return {ok:false, error:String(e && e.message || e)}; } }

var EXPORTS={fixJson:fixJson,tryParseJson:tryParseJson};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.JsonFixForgePure = EXPORTS; }
